# Read one non-secret variable from the protected staging environment.
read_staging_variable() {
  gh variable get "$1" --repo "$REPOSITORY" --env staging 2>/dev/null || true
}

# Write a non-secret staging variable only when its exact value changed.
set_staging_variable() {
  local name="$1" value="$2" current
  current=$(read_staging_variable "$name")
  if [[ "$current" == "$value" ]]; then
    say "$name is already correct; skipping the GitHub write."
    return
  fi
  gh variable set "$name" --repo "$REPOSITORY" --env staging --body "$value"
  [[ "$(read_staging_variable "$name")" == "$value" ]] || {
    warn "$name did not match after the GitHub write"
    exit 1
  }
  say "Set and verified $name in the staging environment."
}

# Load the current digest-pinned workload inputs without accepting payloads.
load_workload_inputs() {
  export TF_VAR_backend_image="$(read_staging_variable GCP_BACKEND_IMAGE)"
  export TF_VAR_frontend_image="$(read_staging_variable GCP_FRONTEND_IMAGE)"
  export TF_VAR_qdrant_secret_version="$(read_staging_variable GCP_QDRANT_SECRET_VERSION)"
  [[ "$TF_VAR_backend_image" == us-west1-docker.pkg.dev/*@sha256:* ]] || {
    warn "GCP_BACKEND_IMAGE is missing or not digest pinned"
    exit 1
  }
  [[ "$TF_VAR_frontend_image" == us-west1-docker.pkg.dev/*@sha256:* ]] || {
    warn "GCP_FRONTEND_IMAGE is missing or not digest pinned"
    exit 1
  }
  [[ "$TF_VAR_qdrant_secret_version" =~ ^[1-9][0-9]*$ ]] || {
    warn "GCP_QDRANT_SECRET_VERSION is missing or not numeric"
    exit 1
  }
}

# Produce and optionally apply the only permitted workload change: the
# backend's exact IAP audience. No frontend, image, database, or secret-version
# change may ride along with this cutover.
apply_workload_audience() {
  local audience="$1" plan_file plan_json invalid_changes change_count
  load_workload_inputs
  export TF_VAR_iap_audience="$audience"
  terraform -chdir="$WORKLOAD_ROOT" init -reconfigure \
    -backend-config="bucket=$STAGING_BUCKET" \
    -backend-config="prefix=workloads"
  plan_file=$(mktemp "${TMPDIR:-/tmp}/aifa-edge-workload.XXXXXX")
  plan_json=$(mktemp "${TMPDIR:-/tmp}/aifa-edge-workload-json.XXXXXX")
  TEMP_FILES+=("$plan_file" "$plan_json")
  terraform -chdir="$WORKLOAD_ROOT" plan -lock-timeout=5m -out="$plan_file"
  terraform -chdir="$WORKLOAD_ROOT" show -no-color "$plan_file"
  terraform -chdir="$WORKLOAD_ROOT" show -json "$plan_file" > "$plan_json"
  invalid_changes=$(jq -r '
    [
      .resource_changes[]?
      | select(.change.actions != ["no-op"])
      | select(
          .address != "module.application_workloads.google_cloud_run_v2_service.backend" or
          any(.change.actions[]; . == "create" or . == "delete")
        )
      | .address
    ] | unique | join(",")
  ' "$plan_json")
  [[ -z "$invalid_changes" ]] || {
    warn "the audience plan contains changes outside the backend service: $invalid_changes"
    exit 1
  }
  change_count=$(jq -r '[.resource_changes[]? | select(.change.actions != ["no-op"])] | length' "$plan_json")
  if [[ "$change_count" == "0" ]]; then
    say "The backend already uses $audience; skipping the workload apply."
    return
  fi
  confirm "Apply only this reviewed backend-audience plan?" || exit 1
  terraform -chdir="$WORKLOAD_ROOT" apply "$plan_file"
}

# Verify the deployed backend received the exact audience after a revision
# update. The assertion is configuration-only and never reads a token.
verify_backend_audience() {
  local audience="$1" description
  description=$(gcloud run services describe "$BACKEND_SERVICE" \
    --project="$PROJECT_ID" --region="$REGION" --format=json)
  jq -e --arg audience "$audience" '
    any(
      .spec.template.spec.containers[]?
      | select(.name == "backend")
      | .env[]?;
      .name == "AIFA_IAP_AUDIENCE" and .value == $audience
    )
  ' <<<"$description" >/dev/null || {
    warn "the deployed backend does not contain the expected IAP audience"
    exit 1
  }
}

# Google can report a managed certificate ACTIVE before every serving frontend
# has converged. Retry both the TLS handshake and the expected anonymous IAP
# challenge for a bounded 30 minutes; never accept an anonymous 2xx response.
wait_for_https_iap_challenge() {
  local url="$1" deadline https_status curl_exit
  deadline=$(( $(date +%s) + TLS_SERVING_TIMEOUT_SECONDS ))
  while true; do
    curl_exit=0
    if https_status=$(curl --silent --output /dev/null --max-time 30 \
      --write-out '%{http_code}' "$url"); then
      if [[ "$https_status" == "302" || "$https_status" == "401" || "$https_status" == "403" ]]; then
        say "HTTPS/IAP readiness status: $https_status"
        return 0
      fi
    else
      curl_exit=$?
      https_status="curl_exit_$curl_exit"
    fi
    (( $(date +%s) < deadline )) || {
      warn "HTTPS/IAP readiness did not converge within 30 minutes; last result: $https_status"
      return 1
    }
    say "HTTPS/IAP readiness is $https_status; retrying in $TLS_RETRY_SECONDS seconds."
    sleep "$TLS_RETRY_SECONDS"
  done
}

