EXISTING_CLIENT_ID=$(read_staging_variable GCP_IAP_OAUTH_CLIENT_ID)
EXISTING_SECRET_VERSION=$(read_staging_variable GCP_IAP_OAUTH_SECRET_VERSION)
if [[ "$EXISTING_CLIENT_ID" =~ ^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$ ]] && \
  [[ "$EXISTING_SECRET_VERSION" =~ ^[1-9][0-9]*$ ]] && \
  gcloud secrets versions describe "$EXISTING_SECRET_VERSION" \
    --secret="$OAUTH_SECRET_ID" --project="$PROJECT_ID" \
    --format='value(state)' 2>/dev/null | grep -qx ENABLED && \
  confirm "Reuse the existing OAuth client and enabled secret version $EXISTING_SECRET_VERSION?"; then
  IAP_OAUTH_CLIENT_ID="$EXISTING_CLIENT_ID"
  IAP_OAUTH_SECRET_VERSION="$EXISTING_SECRET_VERSION"
  say "Reusing the existing non-secret client identifier and numeric secret version."
else
  open_url "https://console.cloud.google.com/auth/branding?project=$PROJECT_ID"
  step "Configure Branding with app name Finance Assistant Demo, support email $OWNER_ACCOUNT, and External audience."
  step "Keep Publishing status Testing and add $OWNER_ACCOUNT as the only test user."
  step "Do not add provider scopes, a logo, viewers, or provider credentials."
  pause "Return here after the branding and External audience exist. Press Enter to continue."
  open_url "https://console.cloud.google.com/auth/clients?project=$PROJECT_ID"
  step "Create or select the Web application client named Finance Assistant IAP."
  step "Copy its non-secret Client ID. Keep the Client secret in the Google console."
  ask IAP_OAUTH_CLIENT_ID "Paste only the OAuth Client ID:"
  [[ "$IAP_OAUTH_CLIENT_ID" =~ ^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$ ]] || {
    warn "the OAuth Client ID has an unexpected shape"
    exit 1
  }
  say "Add this exact Authorized redirect URI to that client:"
  say "https://iap.googleapis.com/v1/oauth/clientIds/${IAP_OAUTH_CLIENT_ID}:handleRedirect"
  pause "Return here after saving the redirect URI. Press Enter to continue."
  LATEST_ENABLED_SECRET_VERSION=$(gcloud secrets versions list "$OAUTH_SECRET_ID" \
    --project="$PROJECT_ID" \
    --filter='state=enabled' \
    --sort-by='~createTime' \
    --limit=1 \
    --format='value(name)')
  LATEST_ENABLED_SECRET_VERSION="${LATEST_ENABLED_SECRET_VERSION##*/}"
  if [[ "$LATEST_ENABLED_SECRET_VERSION" =~ ^[1-9][0-9]*$ ]] && \
    confirm "Reuse enabled Secret Manager version $LATEST_ENABLED_SECRET_VERSION for this OAuth client?"; then
    IAP_OAUTH_SECRET_VERSION="$LATEST_ENABLED_SECRET_VERSION"
    say "Reusing the existing enabled secret version without reading its payload."
  else
    open_url "https://console.cloud.google.com/security/secret-manager/secret/$OAUTH_SECRET_ID/versions?project=$PROJECT_ID"
    step "Choose New version, paste the OAuth Client secret directly, and enable the version."
    warn "Do not paste the secret into this terminal, GitHub, a Terraform variable, or chat."
    pause "Return here after the enabled version exists. Press Enter to continue."
    IAP_OAUTH_SECRET_VERSION=$(gcloud secrets versions list "$OAUTH_SECRET_ID" \
      --project="$PROJECT_ID" \
      --filter='state=enabled' \
      --sort-by='~createTime' \
      --limit=1 \
      --format='value(name)')
    IAP_OAUTH_SECRET_VERSION="${IAP_OAUTH_SECRET_VERSION##*/}"
  fi
fi
[[ "$IAP_OAUTH_SECRET_VERSION" =~ ^[1-9][0-9]*$ ]] || {
  warn "no enabled numeric OAuth secret version exists"
  exit 1
}
export TF_VAR_iap_oauth_client_id="$IAP_OAUTH_CLIENT_ID"
export TF_VAR_iap_oauth_secret_version="$IAP_OAUTH_SECRET_VERSION"
say "Selected numeric secret version $IAP_OAUTH_SECRET_VERSION without reading its payload."

# ── Stage 4: reviewed edge plan and apply before any DNS route exists ─────
stage "Review and create the private edge"
say "The edge is created before DNS while the backend still has a fail-closed audience."
terraform -chdir="$EDGE_ROOT" init -reconfigure \
  -backend-config="bucket=$STAGING_BUCKET" \
  -backend-config="prefix=edge"
EDGE_PLAN=$(mktemp "${TMPDIR:-/tmp}/aifa-edge.XXXXXX")
TEMP_FILES+=("$EDGE_PLAN")
terraform -chdir="$EDGE_ROOT" plan -lock-timeout=5m -out="$EDGE_PLAN"
terraform -chdir="$EDGE_ROOT" show -no-color "$EDGE_PLAN"
confirm "Apply only this reviewed private-edge plan?" || exit 1
terraform -chdir="$EDGE_ROOT" apply "$EDGE_PLAN"
GLOBAL_IP=$(terraform -chdir="$EDGE_ROOT" output -raw global_ip_address)
IAP_AUDIENCE=$(terraform -chdir="$EDGE_ROOT" output -raw backend_iap_audience)
[[ "$GLOBAL_IP" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { warn "invalid global IP output"; exit 1; }
[[ "$IAP_AUDIENCE" =~ ^/projects/${PROJECT_NUMBER}/global/backendServices/[0-9]+$ ]] || {
  warn "invalid backend IAP audience output"
  exit 1
}
say "Created the reviewed edge at $GLOBAL_IP without changing DNS."

# ── Stage 5: exact signed-JWT audience cutover ────────────────────────────
stage "Bind FastAPI to the real IAP audience"
BACKEND_EDGE_ID=$(gcloud compute backend-services describe "$EDGE_BACKEND_SERVICE" \
  --project="$PROJECT_ID" --global --format='value(id)')
[[ "$IAP_AUDIENCE" == "/projects/${PROJECT_NUMBER}/global/backendServices/${BACKEND_EDGE_ID}" ]] || {
  warn "Terraform and Google Cloud disagree on the backend-service audience"
  exit 1
}
apply_workload_audience "$IAP_AUDIENCE"
verify_backend_audience "$IAP_AUDIENCE"
say "FastAPI now accepts only signed assertions for the exact edge backend."

# ── Stage 6: publish only non-secret reconciliation variables ─────────────
stage "Reconcile protected GitHub variables"
set_staging_variable GCP_IAP_OAUTH_CLIENT_ID "$IAP_OAUTH_CLIENT_ID"
set_staging_variable GCP_IAP_OAUTH_SECRET_VERSION "$IAP_OAUTH_SECRET_VERSION"
set_staging_variable GCP_IAP_AUDIENCE "$IAP_AUDIENCE"
say "GitHub stores only the client identifier, numeric secret version, and audience."

# ── Stage 7: operator-controlled Squarespace DNS and certificate wait ─────
stage "Point DNS to the reviewed edge"
say "Add one Squarespace record: Host apps, Type A, Data $GLOBAL_IP."
open_url "https://account.squarespace.com/domains"
step "Open comfforts.com, choose DNS settings, and add or replace only the apps A record."
step "Set its value to $GLOBAL_IP and keep the default TTL."
pause "Return here after saving the record. Press Enter to continue."
confirm "Confirm apps.comfforts.com now points to $GLOBAL_IP?" || exit 1
say "Waiting for Google's managed certificate; status is printed every 30 seconds."
CERTIFICATE_NAME=$(terraform -chdir="$EDGE_ROOT" output -raw certificate_name)
CERTIFICATE_DEADLINE=$(( $(date +%s) + 3600 ))
while true; do
  CERTIFICATE_STATUS=$(gcloud compute ssl-certificates describe "$CERTIFICATE_NAME" \
    --project="$PROJECT_ID" --global --format='value(managed.status)')
  say "Certificate status: $CERTIFICATE_STATUS"
  [[ "$CERTIFICATE_STATUS" == "ACTIVE" ]] && break
  (( $(date +%s) < CERTIFICATE_DEADLINE )) || {
    warn "the certificate did not become ACTIVE within one hour"
    warn "leave the DNS record in place and re-run the wizard later"
    exit 1
  }
  sleep 30
done
say "The certificate is ACTIVE; waiting for HTTPS/IAP serving propagation."
wait_for_https_iap_challenge "$TARGET_URL"

# ── Stage 8: live IAP, TLS, route, IAM, and no-origin qualification ───────
stage "Qualify the assembled private edge"
for edge_service in "$EDGE_BACKEND_SERVICE" "$EDGE_FRONTEND_SERVICE"; do
  EDGE_DESCRIPTION=$(gcloud compute backend-services describe "$edge_service" \
    --project="$PROJECT_ID" --global --format=json)
  jq -e '.iap.enabled == true and (.iap.oauth2ClientId | length > 0)' \
    <<<"$EDGE_DESCRIPTION" >/dev/null || {
    warn "$edge_service is not IAP protected with the custom client"
    exit 1
  }
  EDGE_ID=$(jq -er '.id | tostring' <<<"$EDGE_DESCRIPTION")
  IAP_POLICY=$(gcloud iap web get-iam-policy \
    --project="$PROJECT_ID" \
    --resource-type=backend-services \
    --service="$EDGE_ID" \
    --format=json)
  jq -e --arg owner "$OWNER_MEMBER" '
    [
      .bindings[]?
      | select(.role == "roles/iap.httpsResourceAccessor")
      | .members[]?
    ] == [$owner] and
    all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")
  ' <<<"$IAP_POLICY" >/dev/null || {
    warn "$edge_service has an unexpected IAP access policy"
    exit 1
  }
done
PROJECT_IAM=$(gcloud projects get-iam-policy "$PROJECT_ID" --format=json)
jq -e '
  all(
    .bindings[]?;
    (.role != "roles/iap.httpsResourceAccessor" and .role != "roles/run.invoker") or
    (.members | length == 0)
  )
' <<<"$PROJECT_IAM" >/dev/null || {
  warn "project-level IAP or Cloud Run invocation would broaden the resource-level policies"
  exit 1
}
for service in "$BACKEND_SERVICE" "$FRONTEND_SERVICE"; do
  SERVICE_IAM=$(gcloud run services get-iam-policy "$service" \
    --project="$PROJECT_ID" --region="$REGION" --format=json)
  jq -e --arg iap_agent "serviceAccount:$IAP_SERVICE_AGENT" '
    [
      .bindings[]?
      | select(.role == "roles/run.invoker")
      | .members[]?
    ] == [$iap_agent] and
    all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")
  ' <<<"$SERVICE_IAM" >/dev/null || {
    warn "$service does not have the exact private IAP invocation boundary"
    exit 1
  }
  SERVICE_DESCRIPTION=$(gcloud run services describe "$service" \
    --project="$PROJECT_ID" --region="$REGION" --format=json)
  DIRECT_URL=$(jq -r '.status.url // empty' <<<"$SERVICE_DESCRIPTION")
  if [[ -n "$DIRECT_URL" ]]; then
    DIRECT_PATH="/api/health/live"
    [[ "$service" == "$FRONTEND_SERVICE" ]] && DIRECT_PATH="/finance_assistant/healthz"
    if curl --silent --show-error --fail --max-time 15 \
      "$DIRECT_URL$DIRECT_PATH" >/dev/null 2>&1; then
      warn "$service accepted anonymous direct-origin traffic"
      exit 1
    fi
  fi
done
HTTP_STATUS=$(curl --silent --show-error --output /dev/null --max-time 30 \
  --write-out '%{http_code}' "http://$DOMAIN/finance_assistant")
[[ "$HTTP_STATUS" == "308" || "$HTTP_STATUS" == "301" ]] || {
  warn "plain HTTP did not permanently redirect to HTTPS"
  exit 1
}
open_url "$TARGET_URL"
step "Sign in as $OWNER_ACCOUNT and confirm the Finance Assistant shell and assets load."
step "Confirm the shell reports successful health and identity requests; these prove the API prefix rewrite."
step "Open https://$DOMAIN/ and confirm the authenticated unmatched path returns 404."
confirm "Did owner access succeed and the unmatched path fail closed?" || exit 1
terraform -chdir="$EDGE_ROOT" plan -detailed-exitcode -lock-timeout=5m >/dev/null || {
  PLAN_EXIT=$?
  [[ "$PLAN_EXIT" == "0" ]] || { warn "the final private-edge plan is not drift-free"; exit 1; }
}
REVISION=$(git rev-parse HEAD)
EVIDENCE_FILE="$EVIDENCE_ROOT/private-edge-${REVISION}.v1.json"
jq -n \
  --arg revision "$REVISION" \
  --arg generated_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
  --arg global_ip "$GLOBAL_IP" \
  --arg audience "$IAP_AUDIENCE" \
  --arg owner "$OWNER_MEMBER" \
  '{
    schema_version: "1",
    status: "qualified",
    revision: $revision,
    generated_at: $generated_at,
    target: "https://apps.comfforts.com/finance_assistant",
    global_ip: $global_ip,
    iap_audience: $audience,
    access: {members: [$owner], anonymous: "denied"},
    controls: {
      tls_certificate: "ACTIVE",
      http_redirect: "passed",
      exact_path_routing: "passed",
      api_prefix_rewrite: "passed",
      signed_identity_boundary: "passed",
      direct_origin: "denied",
      unmatched_path: "authenticated_404",
      provider_mode: "credential_free",
      terraform_drift: "none"
    },
    secret_payloads_recorded: false,
    integrated_product_journeys: "pending_next_slice"
  }' > "$EVIDENCE_FILE"
say "Qualified the owner-only edge and wrote secret-free evidence:"
say "$EVIDENCE_FILE"
warn "Commit the evidence on a dedicated branch; integrated product journeys are still pending."

finish
}

run_wizard "$@"; exit
